themes.css:
:root {
	/* Every surface-painting token — anything hardcoded to hsl(220, ...)
	   in color-system.css gets re-anchored at hue 258 so no surface
	   leaks the default cool-grey through. */
	/* Backgrounds */
	--background-primary: hsl(258, 70%, 15%);
	--background-secondary: hsl(258, 65%, 19%);
	--background-secondary-lighter: hsl(258, 60%, 22%);
	--background-secondary-alt: hsl(258, 70%, 17%);
	--background-tertiary: hsl(258, 75%, 9%);
	--background-channel-header: hsl(258, 60%, 21%);
	--background-textarea: hsl(258, 55%, 24%);
	--background-header-primary: hsl(258, 65%, 19%);
	--background-header-primary-hover: hsl(258, 60%, 23%);
	--background-header-secondary: hsl(258, 70%, 15%);
	/* Server sidebar bar — its own token, doesn't cascade */
	--guild-list-foreground: hsl(258, 60%, 18%);
	/* User panel widgets — own borders/dividers, also locked at hue 220 by default */
	--panel-control-border: hsla(258, 50%, 65%, 0.45);
	--panel-control-divider: hsla(258, 50%, 55%, 0.35);
	/* Control buttons (volume, settings rows) — locked at hue 220 by default */
	--control-button-hover-bg: hsl(258, 50%, 25%);
	--control-button-active-bg: hsl(258, 50%, 27%);
	/* Modifier overlays — brand-tinted, low alpha. */
	--background-modifier-hover: hsla(258, 70%, 75%, 0.12);
	--background-modifier-selected: hsla(258, 80%, 75%, 0.25);
	--background-modifier-accent: hsla(258, 50%, 65%, 0.12);
	--background-modifier-accent-focus: hsla(258, 50%, 65%, 0.22);
	/* Borders */
	--border-color: hsl(258, 50%, 30%);
	--border-color-hover: hsla(258, 50%, 50%, 0.3);
	/* Inline code background */
	--bg-code: hsla(258, 65%, 15%, 0.8);
	/* Brand */
	--brand-primary: #a98cf5;
	--brand-secondary: #8b6ddf;
	--brand-primary-light: #c0a8ff;
	--brand-primary-fill: #ffffff;
	--text-on-brand-primary: #ffffff;
	/* Text — every shade re-anchored at hue 258 with low sat */
	--text-primary: #e4e4f7;
	--text-secondary: hsl(258, 25%, 80%);
	--text-tertiary: hsl(258, 25%, 65%);
	--text-tertiary-muted: hsl(258, 25%, 56%);
	--text-tertiary-secondary: hsl(258, 25%, 52%);
	--text-primary-muted: hsl(258, 25%, 78%);
	--text-chat: hsl(258, 25%, 93%);
	--text-chat-muted: hsl(258, 25%, 78%);
	--text-link: #c0a8ff;
}

:root {
	/* Every surface-painting token re-anchored at hue 35. */
	/* Backgrounds */
	--background-primary: hsl(35, 55%, 13%);
	--background-secondary: hsl(35, 50%, 17%);
	--background-secondary-lighter: hsl(35, 48%, 20%);
	--background-secondary-alt: hsl(35, 55%, 15%);
	--background-tertiary: hsl(35, 60%, 8%);
	--background-channel-header: hsl(35, 48%, 19%);
	--background-textarea: hsl(35, 45%, 22%);
	--background-header-primary: hsl(35, 50%, 17%);
	--background-header-primary-hover: hsl(35, 50%, 21%);
	--background-header-secondary: hsl(35, 55%, 13%);
	/* Server sidebar */
	--guild-list-foreground: hsl(35, 48%, 16%);
	/* User panel widgets */
	--panel-control-border: hsla(35, 55%, 65%, 0.45);
	--panel-control-divider: hsla(35, 55%, 55%, 0.35);
	/* Control buttons */
	--control-button-hover-bg: hsl(35, 45%, 25%);
	--control-button-active-bg: hsl(35, 45%, 27%);
	/* Modifier overlays */
	--background-modifier-hover: hsla(35, 70%, 70%, 0.12);
	--background-modifier-selected: hsla(35, 85%, 70%, 0.25);
	--background-modifier-accent: hsla(35, 55%, 60%, 0.12);
	--background-modifier-accent-focus: hsla(35, 55%, 60%, 0.22);
	/* Borders */
	--border-color: hsl(35, 45%, 26%);
	--border-color-hover: hsla(35, 50%, 50%, 0.3);
	/* Inline code */
	--bg-code: hsla(35, 50%, 13%, 0.8);
	/* Brand */
	--brand-primary: #f5b366;
	--brand-secondary: #d99850;
	--brand-primary-light: #f8c585;
	--brand-primary-fill: #1c1814;
	--text-on-brand-primary: #1c1814;
	/* Text — anchored at hue 35 */
	--text-primary: #ebe1d4;
	--text-secondary: hsl(35, 22%, 80%);
	--text-tertiary: hsl(35, 22%, 65%);
	--text-tertiary-muted: hsl(35, 22%, 56%);
	--text-tertiary-secondary: hsl(35, 22%, 52%);
	--text-primary-muted: hsl(35, 22%, 78%);
	--text-chat: hsl(35, 22%, 93%);
	--text-chat-muted: hsl(35, 22%, 78%);
	--text-link: #f8c585;
}
